def solve(grid):
    H,W=len(grid),len(grid[0])
    gl_r=[i for i in range(H) if len(set(grid[i]))==1 and grid[i][0]!=0]
    gl_c=[j for j in range(W) if len({r[j] for r in grid})==1 and grid[0][j]!=0]
    def bands(gl,end):
        bs=[]; s=0
        for g in gl: bs.append((s,g)); s=g+1
        bs.append((s,end)); return bs
    br=bands(gl_r,H); bc=bands(gl_c,W)
    def find(b,i):
        for k,(a,b_) in enumerate(b):
