    out=[row[:] for row in grid]
    from collections import defaultdict
    cells=defaultdict(set)
    for i in range(H):
        for j in range(W):
            v=grid[i][j]
            if v and i not in gl_r and j not in gl_c:
                cells[(v,find(br,i),find(bc,j))].add((i,j))
    bycolor=defaultdict(dict)
    for (v,bi,cj),px in cells.items(): bycolor[v][(bi,cj)]=px
    for v,d in bycolor.items():
        occ=set(d)
        # 2x2 blocks with exactly 3 occupied
        for bi in range(len(br)-1):
            for cj in range(len(bc)-1):
                block=[(bi,cj),(bi,cj+1),(bi+1,cj),(bi+1,cj+1)]
                inb=[c for c in block if c in occ]
                if len(inb)!=3: continue
                miss=[c for c in block if c not in occ][0]
                # transform from an occupied neighbor
                src=None
                for c in inb:
                    dc=abs(c[0]-miss[0])+abs(c[1]-miss[1])
                    if dc==1: src=(c,dc); break
                if src is None: src=(inb[0],2)
                (si,sj),dc=src
                Sr,Sc=br[si][1]-br[si][0], bc[sj][1]-bc[sj][0]
                S={(i-br[si][0], j-bc[sj][0]) for i,j in d[(si,sj)]}
                if dc==1 and si==miss[0]:   # horizontal neighbor -> hmirror
                    T={(r,Sc-1-c) for r,c in S}
                elif dc==1:                 # vertical neighbor -> vmirror
                    T={(Sr-1-r,c) for r,c in S}
                else:
                    T={(Sr-1-r,Sc-1-c) for r,c in S}
                mr,mc=br[miss[0]][0],bc[miss[1]][0]
                for r,c in T:
                    if grid[mr+r][mc+c]==0: out[mr+r][mc+c]=v
    return out

